<?php
if (!defined('SORS_APP')) { http_response_code(404); exit; }
$id=(int)($_GET['user_id'] ?? $_SESSION['user_id']);
$stmt=$conn->prepare('SELECT * FROM users WHERE id=?');$stmt->execute([$id]);$user=$stmt->get_result()->fetch_assoc();
if (!$user) fail_request('We could not find this person. Try searching for their username.',404);
$own=$id==$_SESSION['user_id'];
page_header($own ? 'My Profile' : display_name($user),'profile'); heading($own ? 'My Profile' : 'Profile','A little about you and your learning space.');
echo '<p><a href="/search.php">Find a person by name or username</a></p>';
?><section class="panel"><img class="cover" src="<?= e(profile_image($user['cover_photo'],'cover')) ?>" alt="Cover photo for <?= e(display_name($user)) ?>"><img class="profile-avatar" src="<?= e(profile_image($user['profile_picture'],'profile')) ?>" alt="Profile photo for <?= e(display_name($user)) ?>"><h2><?= e(display_name($user)) ?></h2><p>@<?= e($user['username']) ?> <span class="badge"><?= e(ucfirst($user['role'])) ?></span></p><?php if ($own): ?><p><a href="/feed.php?mine=1">See My Posts</a></p><?php endif; ?></section>
<?php if ($own): ?><div class="grid"><?php foreach (['profile_picture'=>['profile','Change profile photo','upload_profile.php'],'cover_photo'=>['cover','Change cover photo','upload_cover.php']] as $field=>[$kind,$title,$action]): ?><section class="panel"><h2><?= e($title) ?></h2><?php form_open('/'.$action,'',true); ?><div class="field"><label for="<?= e($field) ?>">Choose a new <?= e($kind) ?> photo</label><input type="file" id="<?= e($field) ?>" name="<?= e($field) ?>" accept=".jpg,.jpeg,.png,.gif,.webp" data-preview="preview-<?= e($kind) ?>" aria-describedby="hint-<?= e($kind) ?>" required><span class="hint" id="hint-<?= e($kind) ?>">JPG, PNG, GIF, or WebP. Up to 10 MB. Check the preview, then save.</span><img class="image-preview" id="preview-<?= e($kind) ?>" alt="Preview of your chosen <?= e($kind) ?> photo" hidden></div><button>Save <?= e($kind) ?> photo</button></form></section><?php endforeach; ?></div><?php endif; page_footer();
